arguments.new_string:
resize(scale) {
  const c = this.canvas;
  let w = Math.max(2, Math.round(c.clientWidth * scale));
  let h = Math.max(2, Math.round(c.clientHeight * scale));
  // hard pixel budget: per-pixel ray cost grows fast, and a too-large RT can
  // trip the GPU watchdog (frozen tab -> browser kills the context)
  const MAX_PIXELS = 2_100_000;
  if (w * h > MAX_PIXELS) {
    const k = Math.sqrt(MAX_PIXELS / (w * h));
    w = Math.max(2, Math.floor(w * k));
    h = Math.max(2, Math.floor(h * k));
  }
  if (c.width !== w || c.height !== h) {
    c.width = w;
    c.height = h;
  }
}
